// Manifest export: turn tenant assets into a portable manifest.

/* eslint-disable @typescript-eslint/no-explicit-any -- manifests and untyped table rows are free-form JSON */

import { getConnectorDefinition } from '@/lib/connectors/registry'
import { GITHUB_CONNECTOR_KEY } from '@/lib/github-sync/connection'
import { logDestinationManifestRow } from '@/lib/services/log-destinations'
import { isObjectBackedReference } from './normalize'
import { scrubSecretsForExport, SECRET_PLACEHOLDER } from './scrub'

/**
 * Integrations generated by a tenant connector (tenant_connectors.integration_id).
 * They travel inside the 'connectors' section, never as integrations.
 */
async function connectorIntegrationIds(supabase: any, tenantId: string): Promise<Set<string>> {
  const { data } = await (supabase as any).from('tenant_connectors').select('integration_id').eq('tenant_id', tenantId)
  return new Set(((data ?? []) as any[]).map((row) => row.integration_id).filter(Boolean).map(String))
}

/** Ids per query (see buildManifestExport). */
export const EXPORT_ID_CHUNK = 100

export async function buildManifestExport(
  supabase: any,
  tenantId: string,
  idsByType: Partial<Record<string, string[]>>,
  options: {
    /**
     * Server-side comparison only (config apply plans): keep stored credential
     * values instead of the '__SECRET__' sentinel. Never return such a payload.
     */
    keepCredentials?: boolean
  } = {},
): Promise<Record<string, any>> {
  // Long id lists: one pass per chunk, merged. Each query sends its ids in
  // the URL (`in.(…)`), and the API gateway refuses URLs past ~8 KB — a
  // failed read used to drop the whole section silently (300 workflows
  // exported as none).
  const longest = Math.max(0, ...Object.values(idsByType).map((ids) => ids?.length ?? 0))
  if (longest > EXPORT_ID_CHUNK) {
    const merged: Record<string, any> = {}
    for (let start = 0; start < longest; start += EXPORT_ID_CHUNK) {
      const slice = Object.fromEntries(Object.entries(idsByType)
        .map(([type, ids]) => [type, (ids ?? []).slice(start, start + EXPORT_ID_CHUNK)] as const)
        .filter(([, ids]) => ids.length))
      const part = await buildManifestExport(supabase, tenantId, slice, options)
      for (const [section, rows] of Object.entries(part)) merged[section] = Array.isArray(rows) ? [...(merged[section] ?? []), ...rows] : rows
    }
    return merged
  }

  // Every query is pinned to the tenant: ids are often caller-supplied
  // (config export filters), and a service-role client bypasses RLS, so an id
  // from another tenant must simply match nothing.
  const payload: Record<string, any> = {}

  if (idsByType.workflow?.length) {
    const { data } = await (supabase as any).from('workflows')
      .select('id, name, description, trigger_type, trigger_config, nodes, edges, user_variables, swimlanes, is_active')
      .in('id', idsByType.workflow)
      .eq('tenant_id', tenantId)
    payload.workflows = data ?? []
  }
  if (idsByType.workflow_activity?.length) {
    const { data } = await (supabase as any).from('custom_workflow_activities')
      .select('id, name, description, key, status, source_kind, version, icon_name, color, source_code, manifest, demo_inputs, tags, source_filename')
      .in('id', idsByType.workflow_activity)
      .eq('tenant_id', tenantId)
    payload.workflow_activities = data ?? []
  }
  if (idsByType.data_table?.length) {
    const { data } = await (supabase as any).from('custom_tables')
      .select('id, name, description, columns')
      .in('id', idsByType.data_table)
      .eq('tenant_id', tenantId)
    payload.data_tables = data ?? []
  }
  if (idsByType.retention_policy?.length) {
    const { data } = await (supabase as any).from('retention_policies')
      .select('id, name, description, policy_mode, duration_value, duration_unit, exact_date, applies_to, created_at, updated_at')
      .in('id', idsByType.retention_policy)
      .eq('tenant_id', tenantId)
    payload.retention_policies = data ?? []
  }
  const generatedIntegrations = idsByType.integration?.length ? await connectorIntegrationIds(supabase, tenantId) : new Set<string>()
  const integrationIds = (idsByType.integration ?? []).filter((id) => !generatedIntegrations.has(String(id)))
  if (integrationIds.length) {
    const { data } = await (supabase as any).from('integrations')
      .select('id, name, type, config, is_active, tags')
      .in('id', integrationIds)
      .eq('tenant_id', tenantId)
    const integrations = data ?? []
    // Credentials become the '__SECRET__' sentinel rather than being dropped:
    // an upsert import (config apply, GitHub deploy) then keeps the stored
    // value instead of wiping it, and create-mode imports drop the sentinel.
    const mask = (record: Record<string, unknown> | undefined, keys: string[]) => {
      if (!record || typeof record !== 'object') return
      for (const key of keys) if (record[key] !== undefined && record[key] !== null && record[key] !== '') record[key] = SECRET_PLACEHOLDER
    }
    for (const integration of options.keepCredentials ? [] : integrations) {
      mask(integration.config?.auth_config, ['token', 'password', 'key_value'])
      mask(integration.config?.db_config, ['password'])
    }
    payload.integrations = integrations

    const { data: references } = await (supabase as any).from('integration_references')
      .select('id, integration_id, name, description, tags, request_config, inputs, outputs')
      .in('integration_id', integrationIds)
      .eq('tenant_id', tenantId)
      .order('name')
    payload.references = references ?? []

    const objectBackedReferences = (references ?? []).filter((reference: any) => isObjectBackedReference(reference))
    const objectIds = [...new Set(objectBackedReferences.map((reference: any) => String(reference?.request_config?.object_id ?? '').trim()).filter(Boolean))]
    if (objectIds.length > 0) {
      const { data: objects } = await (supabase as any).from('integration_objects')
        .select('id, name, description, config')
        .in('id', objectIds)
        .eq('tenant_id', tenantId)
      // Sources carry no tenant_id: scope them through the tenant's objects.
      const tenantObjectIds = ((objects ?? []) as Array<{ id: string }>).map((objectRow) => objectRow.id)
      const { data: objectSources } = tenantObjectIds.length > 0
        ? await (supabase as any).from('integration_object_sources')
          .select('*')
          .in('object_id', tenantObjectIds)
          .order('sort_order')
        : { data: [] }

      payload.objects = (objects ?? []).map((objectRow: any) => {
        const generatedReference = objectBackedReferences.find((reference: any) => String(reference?.request_config?.object_id ?? '') === String(objectRow.id))
        return {
          ...objectRow,
          sources: (objectSources ?? []).filter((source: any) => source.object_id === objectRow.id),
          generated_reference_id: generatedReference?.id ?? null,
          generated_reference_name: generatedReference?.name ?? null,
        }
      })
    }
  }
  if (idsByType.email_template?.length) {
    const { data } = await (supabase as any).from('email_templates')
      .select('id, name, description, subject, html_body, text_body, is_default')
      .in('id', idsByType.email_template)
      .eq('tenant_id', tenantId)
    payload.email_templates = data ?? []
  }
  if (idsByType.connector?.length) {
    const { data } = await (supabase as any).from('tenant_connectors')
      .select('id, connector_key, display_name, config, credentials, is_enabled, integration_id')
      .in('id', idsByType.connector)
      .eq('tenant_id', tenantId)
      .neq('connector_key', GITHUB_CONNECTOR_KEY)
    const connectors = ((data ?? []) as any[]).filter((row) => getConnectorDefinition(String(row.connector_key)))
    const integrationIdsOfConnectors = connectors.map((row) => row.integration_id).filter(Boolean)
    const { data: generatedReferences } = integrationIdsOfConnectors.length
      ? await (supabase as any).from('integration_references')
        .select('id, name, integration_id')
        .in('integration_id', integrationIdsOfConnectors)
        .eq('tenant_id', tenantId)
        .order('name')
      : { data: [] }
    // Non-secret config only: every credential (by the definition's
    // credentialFields) is the '__SECRET__' sentinel, whatever is stored —
    // or the stored (encrypted) value for server-side plan comparison.
    payload.connectors = connectors.map((row) => {
      const definition = getConnectorDefinition(String(row.connector_key))!
      const stored = (row.credentials ?? {}) as Record<string, unknown>
      const credentials: Record<string, unknown> = {}
      for (const field of definition.credentialFields) {
        const value = stored[field.key]
        if (value === undefined || value === null || value === '') continue
        credentials[field.key] = options.keepCredentials ? value : SECRET_PLACEHOLDER
      }
      return {
        id: row.id,
        name: row.display_name ?? definition.name,
        connector_key: row.connector_key,
        config: options.keepCredentials ? (row.config ?? {}) : scrubSecretsForExport(row.config ?? {}),
        credentials,
        is_enabled: row.is_enabled ?? false,
        generated_integration_id: row.integration_id ?? null,
        generated_references: ((generatedReferences ?? []) as any[])
          .filter((ref) => row.integration_id && String(ref.integration_id) === String(row.integration_id))
          .map((ref) => ({ id: ref.id, name: ref.name })),
      }
    })
  }
  if (idsByType.form_theme?.length) {
    const { data } = await (supabase as any).from('form_themes')
      .select('id, name, description, overrides')
      .in('id', idsByType.form_theme)
      .eq('tenant_id', tenantId)
      .order('name')
    payload.form_themes = data ?? []
  }
  if (idsByType.form?.length) {
    // The version number is per environment (every import of a content
    // change is a new version there), so it never travels.
    const { data } = await (supabase as any).from('forms')
      .select('id, name, description, tags, fields, layout, theme, buttons, header, submission_retention_days')
      .in('id', idsByType.form)
      .eq('tenant_id', tenantId)
      .order('name')
    // Submissions never travel; an uploaded header image travels as bytes.
    const { embedFormHeaderImages } = await import('./forms')
    payload.forms = await embedFormHeaderImages((data ?? []) as any[])
  }
  if (idsByType.agent?.length) {
    const { data } = await (supabase as any).from('agents')
      .select('id, name, description, model, system_prompt, role, task, boundaries, tools, integration_id, output_config, is_active')
      .in('id', idsByType.agent)
      .eq('tenant_id', tenantId)
    payload.agents = data ?? []
  }
  if (idsByType.decision_table?.length) {
    const { data } = await (supabase as any).from('decision_tables')
      .select('id, name, description, inputs, outputs, rules')
      .in('id', idsByType.decision_table)
      .eq('tenant_id', tenantId)
    payload.decision_tables = data ?? []
  }
  if (idsByType.report?.length) {
    const { data } = await (supabase as any).from('reports')
      .select('id, name, description, category, config, is_shared, created_at, updated_at')
      .in('id', idsByType.report)
      .eq('tenant_id', tenantId)
    payload.reports = data ?? []
  }
  if (idsByType.role?.length) {
    const { data } = await (supabase as any).from('roles')
      .select('id, name, slug, description, permissions, is_system, retention_policy_id')
      .in('id', idsByType.role)
      .eq('tenant_id', tenantId)
    // Only CUSTOM roles travel: system roles are tenant-managed and never
    // exported. is_system is selected purely for this filter and stripped
    // from the manifest rows.
    payload.roles = (data ?? [])
      .filter((role: any) => !role.is_system)
      .map(({ is_system: _isSystem, ...rest }: any) => rest)
  }
  if (idsByType.mcp_server?.length) {
    const { data } = await (supabase as any).from('mcp_servers')
      .select('id, name, url, auth_type, auth_config, is_active')
      .in('id', idsByType.mcp_server)
      .eq('tenant_id', tenantId)
    // Credential material inside auth_config (token/key_value/password) is
    // scrubbed to the '__SECRET__' sentinel unconditionally, mirroring how
    // integration credentials never travel with a manifest. Import restores
    // sentinels from the existing row in upsert mode.
    payload.mcp_servers = options.keepCredentials ? (data ?? []) : (data ?? []).map((server: any) => scrubSecretsForExport(server))
  }
  if (idsByType.log_destination?.length) {
    const { data } = await (supabase as any).from('log_destinations')
      .select('id, name, type, config, credentials, filters, enabled')
      .in('id', idsByType.log_destination)
      .eq('tenant_id', tenantId)
      .order('name')
    // Every credential value is the '__SECRET__' sentinel (or the stored,
    // encrypted value for server-side plan comparison); shipper state
    // (cursor, status, stats) is per-environment and never travels.
    payload.log_destinations = ((data ?? []) as any[]).map((row) => logDestinationManifestRow(row, options.keepCredentials))
  }
  return payload
}

export type TenantExportOptions = {
  /** Secrets are scrubbed to '__SECRET__' by default; opt out with false. */
  scrubSecrets?: boolean
}

/**
 * Export every portable asset in a tenant as a format_version: 3 manifest.
 *
 * All v2 manifest sections keep their exact v2 shape; v3 adds new sections
 * on top: roles (custom roles only; system roles never travel) and
 * mcp_servers (auth_config credentials scrubbed to the '__SECRET__' sentinel).
 *
 * Table content rows never travel: custom_table_rows are excluded by
 * design. Environment-specific config never travels either: api_keys and
 * the GitHub-sync connection are deliberately not exported, and connectors
 * (tenant_connectors) carry their non-secret config only — credentials are
 * always the '__SECRET__' sentinel and their generated integration is left
 * out of the integrations section. Log destinations likewise travel without
 * credentials or shipper state, and forms without their version history.
 */
export async function buildTenantExport(supabase: any, tenantId: string, opts?: TenantExportOptions) {
  const scrubSecrets = opts?.scrubSecrets ?? true

  const selectTenantIds = async (table: string): Promise<string[]> => {
    const { data, error } = await (supabase as any).from(table).select('id').eq('tenant_id', tenantId)
    if (error) throw new Error(error.message)
    return (data ?? []).map((row: any) => row.id)
  }

  const idsByType: Partial<Record<string, string[]>> = {
    workflow: await selectTenantIds('workflows'),
    workflow_activity: await selectTenantIds('custom_workflow_activities'),
    data_table: await selectTenantIds('custom_tables'),
    retention_policy: await selectTenantIds('retention_policies'),
    // integration_references and integration_objects (+sources) ride along
    // with their integrations inside buildManifestExport.
    integration: await selectTenantIds('integrations'),
    agent: await selectTenantIds('agents'),
    decision_table: await selectTenantIds('decision_tables'),
    report: await selectTenantIds('reports'),
    // System roles are filtered out inside buildManifestExport; only custom
    // roles end up in the manifest's `roles` section.
    role: await selectTenantIds('roles'),
    mcp_server: await selectTenantIds('mcp_servers'),
    email_template: await selectTenantIds('email_templates'),
    // The GitHub-sync row and unknown connector keys are filtered out
    // inside buildManifestExport.
    connector: await selectTenantIds('tenant_connectors'),
    // Service-role only table: a member-scoped client simply exports none.
    log_destination: await selectTenantIds('log_destinations').catch(() => []),
    // Reusable task forms and their saved themes (versions stay behind).
    form_theme: await selectTenantIds('form_themes').catch(() => []),
    form: await selectTenantIds('forms').catch(() => []),
  }
  for (const key of Object.keys(idsByType)) {
    if (!idsByType[key]?.length) delete idsByType[key]
  }

  const payload: Record<string, any> = {
    format_version: 3,
    tenant_id: tenantId,
    export_options: {
      include_table_rows: false,
      secrets_scrubbed: scrubSecrets,
    },
  }

  Object.assign(payload, await buildManifestExport(supabase, tenantId, idsByType))

  return scrubSecrets ? scrubSecretsForExport(payload) : payload
}
